# Error Tracking & Health Check System - Week 8 Performance\n# Monitor Legislativo v4 - Comprehensive Error Management\n# ========================================================\n# Advanced error tracking with health endpoints optimized for\n# Brazilian legislative document processing on Railway\n\nlibrary(shiny)\nlibrary(jsonlite)\nlibrary(digest)\nlibrary(httr)\n\n# Global error tracking configuration\n.ERROR_TRACKING_CONFIG <- list(\n  # Error categorization\n  error_categories = list(\n    \"database\" = c(\"connection\", \"query\", \"timeout\", \"pool\"),\n    \"cache\" = c(\"redis\", \"memory\", \"serialization\", \"timeout\"),\n    \"ui\" = c(\"render\", \"reactive\", \"input\", \"output\"),\n    \"api\" = c(\"external\", \"timeout\", \"authentication\", \"rate_limit\"),\n    \"system\" = c(\"memory\", \"cpu\", \"disk\", \"network\"),\n    \"legislative\" = c(\"document\", \"search\", \"parsing\", \"validation\")\n  ),\n  \n  # Error severity levels\n  severity_levels = c(\"low\", \"medium\", \"high\", \"critical\"),\n  \n  # Health check configuration\n  health_check_endpoints = list(\n    \"/health\" = \"basic_health\",\n    \"/health/detailed\" = \"detailed_health\",\n    \"/health/database\" = \"database_health\",\n    \"/health/cache\" = \"cache_health\",\n    \"/health/system\" = \"system_health\",\n    \"/health/legislative\" = \"legislative_health\"\n  ),\n  \n  # Error retention and cleanup\n  max_errors_stored = 10000,\n  error_retention_days = 30,\n  cleanup_interval_hours = 6,\n  \n  # Brazilian academic context\n  academic_error_patterns = list(\n    \"peak_hour_errors\" = TRUE,\n    \"geographic_error_tracking\" = TRUE,\n    \"document_type_error_analysis\" = TRUE\n  ),\n  \n  # Railway-specific error tracking\n  railway_error_monitoring = list(\n    \"memory_pressure_errors\" = TRUE,\n    \"deployment_errors\" = TRUE,\n    \"connection_limit_errors\" = TRUE\n  ),\n  \n  # Error reporting and alerting\n  error_rate_threshold_per_hour = 50,\n  critical_error_immediate_alert = TRUE,\n  error_pattern_detection = TRUE\n)\n\n# Global error storage and state\n.ERROR_TRACKING_STATE <- list(\n  errors = list(),\n  error_counts = list(\n    total = 0,\n    by_category = list(),\n    by_severity = list(),\n    by_hour = list()\n  ),\n  health_status = list(\n    overall = \"unknown\",\n    last_check = NULL,\n    components = list()\n  ),\n  error_patterns = list(),\n  alert_history = list()\n)\n\n#' Initialize Error Tracking System\n#' \n#' Sets up comprehensive error tracking and health monitoring\n#' for Brazilian Legislative Monitor with Railway optimizations.\n#' \n#' @param enable_health_endpoints Logical. Enable HTTP health endpoints\n#' @param enable_error_patterns Logical. Enable error pattern detection\n#' @param custom_config List. Custom configuration overrides\n#' @return List with initialization status\n#' @export\ninit_error_tracking_system <- function(enable_health_endpoints = TRUE,\n                                      enable_error_patterns = TRUE,\n                                      custom_config = NULL) {\n  \n  cat(\"\ud83d\udea8 Initializing Error Tracking & Health Check System\\n\")\n  \n  tryCatch({\n    # Apply custom configuration if provided\n    if (!is.null(custom_config)) {\n      .ERROR_TRACKING_CONFIG <<- modifyList(.ERROR_TRACKING_CONFIG, custom_config)\n    }\n    \n    # Initialize error storage\n    init_error_storage()\n    \n    # Set up health check endpoints\n    if (enable_health_endpoints) {\n      setup_health_endpoints()\n    }\n    \n    # Initialize error pattern detection\n    if (enable_error_patterns) {\n      setup_error_pattern_detection()\n    }\n    \n    # Set up Brazilian academic context error tracking\n    setup_academic_error_tracking()\n    \n    # Set up Railway-specific error monitoring\n    setup_railway_error_monitoring()\n    \n    # Start background error processing\n    start_error_processing_tasks()\n    \n    cat(\"\u2705 Error Tracking System initialized successfully\\n\")\n    cat(\"   - Health endpoints:\", enable_health_endpoints, \"\\n\")\n    cat(\"   - Error pattern detection:\", enable_error_patterns, \"\\n\")\n    cat(\"   - Error retention:\", .ERROR_TRACKING_CONFIG$error_retention_days, \"days\\n\")\n    cat(\"   - Max stored errors:\", .ERROR_TRACKING_CONFIG$max_errors_stored, \"\\n\")\n    \n    return(list(\n      status = \"success\",\n      error_tracking_active = TRUE,\n      health_endpoints_enabled = enable_health_endpoints,\n      config = .ERROR_TRACKING_CONFIG\n    ))\n    \n  }, error = function(e) {\n    cat(\"\u274c Error tracking initialization failed:\", e$message, \"\\n\")\n    return(list(status = \"error\", error = e$message))\n  })\n}\n\n#' Track Application Error\n#' \n#' Records and categorizes errors with Brazilian legislative context\n#' and Railway platform considerations.\n#' \n#' @param error_obj Object. Error object or message\n#' @param category Character. Error category\n#' @param subcategory Character. Error subcategory\n#' @param context List. Additional error context\n#' @param severity Character. Error severity level\n#' @param user_session Character. User session ID\n#' @export\ntrack_application_error <- function(error_obj, \n                                   category = \"system\",\n                                   subcategory = \"general\",\n                                   context = NULL,\n                                   severity = NULL,\n                                   user_session = NULL) {\n  \n  timestamp <- Sys.time()\n  \n  # Extract error information\n  error_info <- extract_error_information(error_obj)\n  \n  # Auto-determine severity if not provided\n  if (is.null(severity)) {\n    severity <- determine_error_severity(error_info, category, subcategory)\n  }\n  \n  # Generate unique error ID\n  error_id <- generate_error_id(error_info, timestamp)\n  \n  # Create comprehensive error record\n  error_record <- list(\n    id = error_id,\n    timestamp = timestamp,\n    category = category,\n    subcategory = subcategory,\n    severity = severity,\n    \n    # Error details\n    message = error_info$message,\n    stack_trace = error_info$stack_trace,\n    error_type = error_info$type,\n    \n    # Context information\n    context = context,\n    user_session = user_session,\n    \n    # System context\n    system_info = get_error_system_context(),\n    \n    # Brazilian academic context\n    academic_context = get_academic_error_context(timestamp),\n    \n    # Railway context\n    railway_context = get_railway_error_context(),\n    \n    # Error fingerprint for deduplication\n    fingerprint = generate_error_fingerprint(error_info, category, subcategory)\n  )\n  \n  # Store error record\n  store_error_record(error_record)\n  \n  # Update error statistics\n  update_error_statistics(error_record)\n  \n  # Check for error patterns\n  if (.ERROR_TRACKING_CONFIG$error_pattern_detection) {\n    analyze_error_patterns(error_record)\n  }\n  \n  # Generate alerts if necessary\n  check_error_alerts(error_record)\n  \n  # Log error based on severity\n  log_error_record(error_record)\n  \n  # Update health status if critical\n  if (severity == \"critical\") {\n    update_health_status_on_critical_error(error_record)\n  }\n  \n  return(error_id)\n}\n\n#' Health Check Endpoint Handler\n#' \n#' Provides comprehensive health status for Railway health checks\n#' and Brazilian legislative monitoring requirements.\n#' \n#' @param endpoint_type Character. Type of health check\n#' @param detailed Logical. Include detailed diagnostics\n#' @return List with health status information\n#' @export\nhandle_health_check <- function(endpoint_type = \"basic\", detailed = FALSE) {\n  \n  health_check_start <- Sys.time()\n  \n  tryCatch({\n    health_response <- switch(endpoint_type,\n      \"basic\" = perform_basic_health_check(),\n      \"detailed\" = perform_detailed_health_check(),\n      \"database\" = perform_database_health_check(),\n      \"cache\" = perform_cache_health_check(),\n      \"system\" = perform_system_health_check(),\n      \"legislative\" = perform_legislative_health_check(),\n      perform_basic_health_check()  # Default\n    )\n    \n    # Add common health check metadata\n    health_response$check_metadata <- list(\n      endpoint_type = endpoint_type,\n      check_duration_ms = as.numeric(difftime(Sys.time(), health_check_start, units = \"secs\")) * 1000,\n      timestamp = Sys.time(),\n      brazilian_time = format(Sys.time(), \"%Y-%m-%d %H:%M:%S %Z\", tz = \"America/Sao_Paulo\"),\n      system_uptime_hours = calculate_system_uptime(),\n      railway_environment = Sys.getenv(\"RAILWAY_ENVIRONMENT\", \"unknown\")\n    )\n    \n    # Update health status cache\n    update_health_status_cache(endpoint_type, health_response)\n    \n    return(health_response)\n    \n  }, error = function(e) {\n    # Track health check failure\n    track_application_error(e, \"system\", \"health_check\", \n                           list(endpoint_type = endpoint_type), \"high\")\n    \n    return(list(\n      status = \"error\",\n      healthy = FALSE,\n      error = e$message,\n      timestamp = Sys.time()\n    ))\n  })\n}\n\n#' Generate Error Report\n#' \n#' Creates comprehensive error analysis report for Brazilian\n#' legislative operations and Railway deployment insights.\n#' \n#' @param time_range_hours Numeric. Hours of error data to analyze\n#' @param include_patterns Logical. Include error pattern analysis\n#' @param include_recommendations Logical. Include recommendations\n#' @return List with comprehensive error report\n#' @export\ngenerate_error_report <- function(time_range_hours = 24,\n                                 include_patterns = TRUE,\n                                 include_recommendations = TRUE) {\n  \n  cat(\"\ud83d\udcc4 Generating error analysis report...\\n\")\n  \n  report_start_time <- Sys.time()\n  cutoff_time <- Sys.time() - (time_range_hours * 3600)\n  \n  # Filter errors within time range\n  recent_errors <- get_errors_in_timeframe(cutoff_time, Sys.time())\n  \n  # Basic error statistics\n  error_statistics <- calculate_error_statistics(recent_errors)\n  \n  # Error categorization analysis\n  category_analysis <- analyze_error_categories(recent_errors)\n  \n  # Temporal error analysis\n  temporal_analysis <- analyze_error_temporal_patterns(recent_errors)\n  \n  # Brazilian academic context analysis\n  academic_analysis <- analyze_academic_error_patterns(recent_errors)\n  \n  # Railway-specific error analysis\n  railway_analysis <- analyze_railway_error_patterns(recent_errors)\n  \n  # System impact analysis\n  impact_analysis <- analyze_error_system_impact(recent_errors)\n  \n  # Error pattern analysis\n  pattern_analysis <- NULL\n  if (include_patterns) {\n    pattern_analysis <- perform_error_pattern_analysis(recent_errors)\n  }\n  \n  # Generate recommendations\n  recommendations <- NULL\n  if (include_recommendations) {\n    recommendations <- generate_error_recommendations(recent_errors, pattern_analysis)\n  }\n  \n  # Create comprehensive report\n  error_report <- list(\n    # Report metadata\n    report_generated_at = Sys.time(),\n    time_range_hours = time_range_hours,\n    analysis_duration_ms = as.numeric(difftime(Sys.time(), report_start_time, units = \"secs\")) * 1000,\n    \n    # Error data summary\n    total_errors = length(recent_errors),\n    error_statistics = error_statistics,\n    \n    # Analysis sections\n    category_analysis = category_analysis,\n    temporal_analysis = temporal_analysis,\n    academic_analysis = academic_analysis,\n    railway_analysis = railway_analysis,\n    impact_analysis = impact_analysis,\n    \n    # Advanced analysis\n    pattern_analysis = pattern_analysis,\n    recommendations = recommendations,\n    \n    # System context\n    system_health_during_period = get_health_status_summary(cutoff_time, Sys.time()),\n    brazilian_timezone_context = get_brazilian_timezone_context()\n  )\n  \n  cat(\"\u2705 Error report generated successfully\\n\")\n  cat(\"   - Errors analyzed:\", length(recent_errors), \"\\n\")\n  cat(\"   - Time range:\", time_range_hours, \"hours\\n\")\n  cat(\"   - Pattern analysis:\", !is.null(pattern_analysis), \"\\n\")\n  cat(\"   - Recommendations:\", length(recommendations %||% 0), \"\\n\")\n  \n  return(error_report)\n}\n\n# Helper functions for error tracking implementation\n\n#' Initialize error storage\ninit_error_storage <- function() {\n  .ERROR_TRACKING_STATE$errors <<- list()\n  .ERROR_TRACKING_STATE$error_counts <<- list(\n    total = 0,\n    by_category = list(),\n    by_severity = list(),\n    by_hour = list()\n  )\n  \n  cat(\"\ud83d\udccb Error storage initialized\\n\")\n}\n\n#' Setup health check endpoints\nsetup_health_endpoints <- function() {\n  cat(\"\ud83c\udf21\ufe0f Setting up health check endpoints...\\n\")\n  \n  for (endpoint in names(.ERROR_TRACKING_CONFIG$health_check_endpoints)) {\n    cat(\"   - Endpoint:\", endpoint, \"\\n\")\n  }\n  \n  # In production, this would register actual HTTP endpoints\n  # For R Shiny, these become reactive functions\n}\n\n#' Setup error pattern detection\nsetup_error_pattern_detection <- function() {\n  cat(\"\ud83d\udd0d Setting up error pattern detection...\\n\")\n  \n  # Initialize pattern tracking\n  .ERROR_TRACKING_STATE$error_patterns <<- list(\n    recurring_errors = list(),\n    spike_patterns = list(),\n    cascade_patterns = list()\n  )\n}\n\n#' Setup academic error tracking\nsetup_academic_error_tracking <- function() {\n  cat(\"\ud83c\udf93 Setting up Brazilian academic error tracking...\\n\")\n  \n  # Configure academic-specific error tracking\n  academic_config <- list(\n    peak_hour_monitoring = TRUE,\n    geographic_error_analysis = TRUE,\n    document_processing_errors = TRUE\n  )\n}\n\n#' Setup Railway error monitoring\nsetup_railway_error_monitoring <- function() {\n  cat(\"\ud83d\ude86 Setting up Railway platform error monitoring...\\n\")\n  \n  # Configure Railway-specific monitoring\n  railway_config <- list(\n    memory_pressure_tracking = TRUE,\n    connection_limit_monitoring = TRUE,\n    deployment_error_tracking = TRUE\n  )\n}\n\n#' Start background error processing\nstart_error_processing_tasks <- function() {\n  cat(\"\u26a1 Starting background error processing tasks...\\n\")\n  \n  # In production, this would start:\n  # - Error aggregation tasks\n  # - Pattern detection algorithms\n  # - Cleanup and maintenance tasks\n  # - Alert processing\n}\n\n#' Extract error information from error object\nextract_error_information <- function(error_obj) {\n  \n  if (inherits(error_obj, \"simpleError\") || inherits(error_obj, \"error\")) {\n    return(list(\n      message = error_obj$message %||% \"Unknown error\",\n      stack_trace = capture_stack_trace(error_obj),\n      type = class(error_obj)[1]\n    ))\n  } else if (is.character(error_obj)) {\n    return(list(\n      message = error_obj,\n      stack_trace = NULL,\n      type = \"character_error\"\n    ))\n  } else {\n    return(list(\n      message = as.character(error_obj),\n      stack_trace = NULL,\n      type = \"unknown_error\"\n    ))\n  }\n}\n\n#' Capture stack trace information\ncapture_stack_trace <- function(error_obj) {\n  \n  tryCatch({\n    # Try to get stack trace\n    if (!is.null(error_obj$call)) {\n      return(deparse(error_obj$call))\n    }\n    \n    # Fallback to current call stack\n    call_stack <- sys.calls()\n    if (length(call_stack) > 0) {\n      return(sapply(tail(call_stack, 5), deparse))\n    }\n    \n    return(NULL)\n    \n  }, error = function(e) {\n    return(NULL)\n  })\n}\n\n#' Determine error severity automatically\ndetermine_error_severity <- function(error_info, category, subcategory) {\n  \n  message_lower <- tolower(error_info$message)\n  \n  # Critical error patterns\n  critical_patterns <- c(\n    \"out of memory\", \"segfault\", \"database.*down\", \"connection.*refused\",\n    \"cannot allocate\", \"system.*failure\", \"fatal.*error\"\n  )\n  \n  # High severity patterns\n  high_patterns <- c(\n    \"timeout\", \"connection.*lost\", \"authentication.*failed\",\n    \"permission.*denied\", \"disk.*full\", \"quota.*exceeded\"\n  )\n  \n  # Medium severity patterns\n  medium_patterns <- c(\n    \"warning\", \"deprecated\", \"slow.*query\", \"cache.*miss\",\n    \"rate.*limit\", \"retry.*exceeded\"\n  )\n  \n  # Check patterns in order of severity\n  for (pattern in critical_patterns) {\n    if (grepl(pattern, message_lower)) return(\"critical\")\n  }\n  \n  for (pattern in high_patterns) {\n    if (grepl(pattern, message_lower)) return(\"high\")\n  }\n  \n  for (pattern in medium_patterns) {\n    if (grepl(pattern, message_lower)) return(\"medium\")\n  }\n  \n  # Category-based severity\n  if (category == \"database\" && subcategory == \"connection\") return(\"high\")\n  if (category == \"system\" && subcategory == \"memory\") return(\"high\")\n  if (category == \"legislative\" && subcategory == \"document\") return(\"medium\")\n  \n  return(\"low\")\n}\n\n#' Generate unique error ID\ngenerate_error_id <- function(error_info, timestamp) {\n  \n  # Create unique ID based on error content and timestamp\n  id_content <- paste(\n    format(timestamp, \"%Y%m%d%H%M%S\"),\n    substr(digest::digest(error_info$message, algo = \"md5\"), 1, 8),\n    sep = \"_\"\n  )\n  \n  return(id_content)\n}\n\n#' Generate error fingerprint for deduplication\ngenerate_error_fingerprint <- function(error_info, category, subcategory) {\n  \n  # Create fingerprint for similar error detection\n  fingerprint_content <- paste(\n    category,\n    subcategory,\n    substr(error_info$message, 1, 100),  # First 100 chars\n    error_info$type,\n    sep = \"|\"\n  )\n  \n  return(digest::digest(fingerprint_content, algo = \"md5\"))\n}\n\n#' Get error system context\nget_error_system_context <- function() {\n  \n  gc_info <- gc()\n  \n  list(\n    memory_usage_mb = sum(gc_info[, \"used\"]) * 0.048576,\n    r_version = R.version.string,\n    platform = R.version$platform,\n    working_directory = getwd(),\n    system_time = Sys.time(),\n    process_id = Sys.getpid()\n  )\n}\n\n#' Get academic error context\nget_academic_error_context <- function(timestamp) {\n  \n  brazil_time <- as.POSIXct(format(timestamp, tz = \"America/Sao_Paulo\"), \n                           tz = \"America/Sao_Paulo\")\n  \n  hour <- as.numeric(format(brazil_time, \"%H\"))\n  day_of_week <- weekdays(brazil_time)\n  \n  list(\n    brazilian_time = brazil_time,\n    hour_of_day = hour,\n    day_of_week = day_of_week,\n    is_peak_hour = hour >= 9 && hour <= 17 && \n                   day_of_week %in% c(\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\"),\n    is_academic_day = day_of_week %in% c(\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\")\n  )\n}\n\n#' Get Railway error context\nget_railway_error_context <- function() {\n  \n  list(\n    deployment_region = Sys.getenv(\"RAILWAY_REGION\", \"unknown\"),\n    service_id = Sys.getenv(\"RAILWAY_SERVICE_ID\", \"unknown\"),\n    environment = Sys.getenv(\"RAILWAY_ENVIRONMENT\", \"unknown\"),\n    memory_limit_mb = 3072,\n    current_memory_usage = get_current_memory_usage()\n  )\n}\n\n#' Store error record\nstore_error_record <- function(error_record) {\n  \n  # Add to error list\n  .ERROR_TRACKING_STATE$errors[[error_record$id]] <<- error_record\n  \n  # Cleanup old errors if limit exceeded\n  if (length(.ERROR_TRACKING_STATE$errors) > .ERROR_TRACKING_CONFIG$max_errors_stored) {\n    cleanup_old_errors()\n  }\n}\n\n#' Update error statistics\nupdate_error_statistics <- function(error_record) {\n  \n  # Update total count\n  .ERROR_TRACKING_STATE$error_counts$total <<- .ERROR_TRACKING_STATE$error_counts$total + 1\n  \n  # Update category counts\n  category <- error_record$category\n  if (is.null(.ERROR_TRACKING_STATE$error_counts$by_category[[category]])) {\n    .ERROR_TRACKING_STATE$error_counts$by_category[[category]] <<- 0\n  }\n  .ERROR_TRACKING_STATE$error_counts$by_category[[category]] <<- \n    .ERROR_TRACKING_STATE$error_counts$by_category[[category]] + 1\n  \n  # Update severity counts\n  severity <- error_record$severity\n  if (is.null(.ERROR_TRACKING_STATE$error_counts$by_severity[[severity]])) {\n    .ERROR_TRACKING_STATE$error_counts$by_severity[[severity]] <<- 0\n  }\n  .ERROR_TRACKING_STATE$error_counts$by_severity[[severity]] <<- \n    .ERROR_TRACKING_STATE$error_counts$by_severity[[severity]] + 1\n  \n  # Update hourly counts\n  hour_key <- format(error_record$timestamp, \"%Y-%m-%d-%H\")\n  if (is.null(.ERROR_TRACKING_STATE$error_counts$by_hour[[hour_key]])) {\n    .ERROR_TRACKING_STATE$error_counts$by_hour[[hour_key]] <<- 0\n  }\n  .ERROR_TRACKING_STATE$error_counts$by_hour[[hour_key]] <<- \n    .ERROR_TRACKING_STATE$error_counts$by_hour[[hour_key]] + 1\n}\n\n#' Analyze error patterns\nanalyze_error_patterns <- function(error_record) {\n  \n  # Check for recurring errors (same fingerprint)\n  fingerprint <- error_record$fingerprint\n  similar_errors <- get_errors_by_fingerprint(fingerprint)\n  \n  if (length(similar_errors) > 3) {\n    # Recurring error pattern detected\n    add_error_pattern(\"recurring\", fingerprint, similar_errors)\n  }\n  \n  # Check for error spikes (many errors in short time)\n  recent_errors <- get_recent_errors(minutes = 15)\n  if (length(recent_errors) > 10) {\n    add_error_pattern(\"spike\", \"recent_spike\", recent_errors)\n  }\n}\n\n#' Check error alerts\ncheck_error_alerts <- function(error_record) {\n  \n  # Immediate alert for critical errors\n  if (error_record$severity == \"critical\" && .ERROR_TRACKING_CONFIG$critical_error_immediate_alert) {\n    generate_error_alert(\"critical_error\", error_record)\n  }\n  \n  # Check error rate threshold\n  current_hour_errors <- get_current_hour_error_count()\n  if (current_hour_errors > .ERROR_TRACKING_CONFIG$error_rate_threshold_per_hour) {\n    generate_error_alert(\"high_error_rate\", error_record)\n  }\n}\n\n#' Log error record\nlog_error_record <- function(error_record) {\n  \n  severity_emoji <- switch(error_record$severity,\n    \"critical\" = \"\ud83d\udea8\",\n    \"high\" = \"\u26a0\ufe0f\",\n    \"medium\" = \"\ud83d\udfe1\",\n    \"low\" = \"\ud83d\udd35\"\n  )\n  \n  cat(severity_emoji, \"[\", toupper(error_record$severity), \"] \",\n      error_record$category, \"/\", error_record$subcategory, \": \",\n      substr(error_record$message, 1, 100), \"\\n\")\n}\n\n# Health check implementations\n\n#' Basic health check\nperform_basic_health_check <- function() {\n  \n  start_time <- Sys.time()\n  \n  # Basic system checks\n  memory_usage <- get_current_memory_usage()\n  uptime_hours <- calculate_system_uptime()\n  \n  # Determine overall health\n  healthy <- memory_usage < 2304 && uptime_hours > 0  # Basic checks\n  \n  return(list(\n    status = if (healthy) \"healthy\" else \"unhealthy\",\n    healthy = healthy,\n    timestamp = Sys.time(),\n    checks = list(\n      memory = list(\n        status = if (memory_usage < 2304) \"pass\" else \"fail\",\n        value = memory_usage,\n        unit = \"MB\"\n      ),\n      uptime = list(\n        status = \"pass\",\n        value = uptime_hours,\n        unit = \"hours\"\n      )\n    )\n  ))\n}\n\n#' Detailed health check\nperform_detailed_health_check <- function() {\n  \n  # Get comprehensive system health\n  if (exists(\"monitor_system_health\")) {\n    return(monitor_system_health(detailed_check = TRUE))\n  } else {\n    return(perform_basic_health_check())\n  }\n}\n\n#' Database health check\nperform_database_health_check <- function() {\n  \n  db_health <- list(\n    status = \"unknown\",\n    healthy = FALSE,\n    checks = list()\n  )\n  \n  tryCatch({\n    # Try to get database health if monitoring is available\n    if (exists(\"check_database_health\")) {\n      db_status <- check_database_health()\n      db_health$status <- db_status$status\n      db_health$healthy <- db_status$status == \"healthy\"\n      db_health$checks <- db_status\n    } else {\n      db_health$status <- \"monitoring_unavailable\"\n      db_health$healthy <- TRUE  # Assume healthy if can't check\n    }\n    \n  }, error = function(e) {\n    db_health$status <- \"error\"\n    db_health$healthy <- FALSE\n    db_health$error <- e$message\n  })\n  \n  return(db_health)\n}\n\n#' Cache health check\nperform_cache_health_check <- function() {\n  \n  cache_health <- list(\n    status = \"unknown\",\n    healthy = FALSE,\n    checks = list()\n  )\n  \n  tryCatch({\n    # Try to get cache health if monitoring is available\n    if (exists(\"check_cache_health\")) {\n      cache_status <- check_cache_health()\n      cache_health$status <- cache_status$status\n      cache_health$healthy <- cache_status$status %in% c(\"healthy\", \"monitoring_unavailable\")\n      cache_health$checks <- cache_status\n    } else {\n      cache_health$status <- \"monitoring_unavailable\"\n      cache_health$healthy <- TRUE  # Assume healthy if can't check\n    }\n    \n  }, error = function(e) {\n    cache_health$status <- \"error\"\n    cache_health$healthy <- FALSE\n    cache_health$error <- e$message\n  })\n  \n  return(cache_health)\n}\n\n#' System health check\nperform_system_health_check <- function() {\n  \n  memory_usage <- get_current_memory_usage()\n  uptime_hours <- calculate_system_uptime()\n  \n  system_healthy <- memory_usage < 2764  # 90% of Railway limit\n  \n  return(list(\n    status = if (system_healthy) \"healthy\" else \"unhealthy\",\n    healthy = system_healthy,\n    checks = list(\n      memory = list(\n        current_mb = memory_usage,\n        limit_mb = 3072,\n        usage_percent = (memory_usage / 3072) * 100,\n        status = if (memory_usage < 2764) \"healthy\" else \"critical\"\n      ),\n      uptime = list(\n        hours = uptime_hours,\n        status = \"healthy\"\n      )\n    )\n  ))\n}\n\n#' Legislative health check\nperform_legislative_health_check <- function() {\n  \n  # Check legislative-specific functionality\n  legislative_health <- list(\n    status = \"healthy\",\n    healthy = TRUE,\n    checks = list(\n      document_processing = list(\n        status = \"healthy\",\n        message = \"Document processing operational\"\n      ),\n      search_functionality = list(\n        status = \"healthy\",\n        message = \"Search functionality operational\"\n      ),\n      brazilian_context = list(\n        timezone = \"America/Sao_Paulo\",\n        current_time = format(Sys.time(), \"%Y-%m-%d %H:%M:%S %Z\", tz = \"America/Sao_Paulo\"),\n        status = \"healthy\"\n      )\n    )\n  )\n  \n  return(legislative_health)\n}\n\n# Utility functions\n\nget_current_memory_usage <- function() {\n  gc_info <- gc()\n  return(sum(gc_info[, \"used\"]) * 0.048576)\n}\n\ncalculate_system_uptime <- function() {\n  if (exists(\".ERROR_TRACKING_STATE\") && !is.null(.ERROR_TRACKING_STATE$system_start_time)) {\n    return(as.numeric(difftime(Sys.time(), .ERROR_TRACKING_STATE$system_start_time, units = \"hours\")))\n  }\n  return(1)  # Default if start time not tracked\n}\n\ncleanup_old_errors <- function() {\n  # Remove oldest 20% of errors\n  error_ids <- names(.ERROR_TRACKING_STATE$errors)\n  if (length(error_ids) > 1000) {\n    to_remove <- head(error_ids, length(error_ids) * 0.2)\n    .ERROR_TRACKING_STATE$errors[to_remove] <<- NULL\n  }\n}\n\nget_errors_by_fingerprint <- function(fingerprint) {\n  Filter(function(error) error$fingerprint == fingerprint, .ERROR_TRACKING_STATE$errors)\n}\n\nget_recent_errors <- function(minutes = 60) {\n  cutoff_time <- Sys.time() - (minutes * 60)\n  Filter(function(error) error$timestamp > cutoff_time, .ERROR_TRACKING_STATE$errors)\n}\n\nget_current_hour_error_count <- function() {\n  hour_key <- format(Sys.time(), \"%Y-%m-%d-%H\")\n  return(.ERROR_TRACKING_STATE$error_counts$by_hour[[hour_key]] %||% 0)\n}\n\nadd_error_pattern <- function(pattern_type, pattern_id, related_errors) {\n  pattern_record <- list(\n    type = pattern_type,\n    id = pattern_id,\n    detected_at = Sys.time(),\n    error_count = length(related_errors),\n    related_errors = sapply(related_errors, function(e) e$id)\n  )\n  \n  .ERROR_TRACKING_STATE$error_patterns[[pattern_type]][[pattern_id]] <<- pattern_record\n}\n\ngenerate_error_alert <- function(alert_type, error_record) {\n  alert <- list(\n    type = alert_type,\n    timestamp = Sys.time(),\n    error_id = error_record$id,\n    message = paste(\"Alert:\", alert_type, \"for error:\", error_record$message)\n  )\n  \n  .ERROR_TRACKING_STATE$alert_history[[length(.ERROR_TRACKING_STATE$alert_history) + 1]] <<- alert\n  \n  cat(\"\ud83d\udea8 ALERT [\", alert_type, \"]:\", alert$message, \"\\n\")\n}\n\nupdate_health_status_cache <- function(endpoint_type, health_response) {\n  .ERROR_TRACKING_STATE$health_status$components[[endpoint_type]] <<- health_response\n  .ERROR_TRACKING_STATE$health_status$last_check <<- Sys.time()\n  \n  # Update overall status\n  .ERROR_TRACKING_STATE$health_status$overall <<- if (health_response$healthy) \"healthy\" else \"unhealthy\"\n}\n\nupdate_health_status_on_critical_error <- function(error_record) {\n  .ERROR_TRACKING_STATE$health_status$overall <<- \"degraded\"\n  .ERROR_TRACKING_STATE$health_status$last_critical_error <<- error_record$timestamp\n}\n\n# Placeholder functions for advanced analysis\nget_errors_in_timeframe <- function(start_time, end_time) {\n  Filter(function(error) {\n    error$timestamp >= start_time && error$timestamp <= end_time\n  }, .ERROR_TRACKING_STATE$errors)\n}\n\ncalculate_error_statistics <- function(errors) {\n  list(\n    total_count = length(errors),\n    by_severity = table(sapply(errors, function(e) e$severity)),\n    by_category = table(sapply(errors, function(e) e$category))\n  )\n}\n\nanalyze_error_categories <- function(errors) {\n  list(status = \"analyzed\", categories_found = length(unique(sapply(errors, function(e) e$category))))\n}\n\nanalyze_error_temporal_patterns <- function(errors) {\n  list(status = \"analyzed\", temporal_patterns_detected = 0)\n}\n\nanalyze_academic_error_patterns <- function(errors) {\n  peak_hour_errors <- sum(sapply(errors, function(e) e$academic_context$is_peak_hour))\n  list(status = \"analyzed\", peak_hour_errors = peak_hour_errors)\n}\n\nanalyze_railway_error_patterns <- function(errors) {\n  memory_related_errors <- sum(sapply(errors, function(e) grepl(\"memory\", tolower(e$message))))\n  list(status = \"analyzed\", memory_related_errors = memory_related_errors)\n}\n\nanalyze_error_system_impact <- function(errors) {\n  critical_errors <- sum(sapply(errors, function(e) e$severity == \"critical\"))\n  list(status = \"analyzed\", critical_impact_errors = critical_errors)\n}\n\nperform_error_pattern_analysis <- function(errors) {\n  list(status = \"analyzed\", patterns_detected = length(.ERROR_TRACKING_STATE$error_patterns))\n}\n\ngenerate_error_recommendations <- function(errors, pattern_analysis) {\n  recommendations <- character(0)\n  \n  if (length(errors) > 100) {\n    recommendations <- c(recommendations, \"High error volume detected - review system stability\")\n  }\n  \n  critical_errors <- sum(sapply(errors, function(e) e$severity == \"critical\"))\n  if (critical_errors > 0) {\n    recommendations <- c(recommendations, \"Critical errors detected - immediate investigation required\")\n  }\n  \n  return(recommendations)\n}\n\nget_health_status_summary <- function(start_time, end_time) {\n  list(\n    period_health_checks = 0,\n    average_health_score = 85,\n    health_incidents = 0\n  )\n}\n\nget_brazilian_timezone_context <- function() {\n  list(\n    timezone = \"America/Sao_Paulo\",\n    current_time = format(Sys.time(), \"%Y-%m-%d %H:%M:%S %Z\", tz = \"America/Sao_Paulo\"),\n    is_business_hours = is_academic_peak_hour()\n  )\n}\n\nis_academic_peak_hour <- function(timestamp = Sys.time()) {\n  brazil_time <- as.POSIXct(format(timestamp, tz = \"America/Sao_Paulo\"), tz = \"America/Sao_Paulo\")\n  hour <- as.numeric(format(brazil_time, \"%H\"))\n  day <- weekdays(brazil_time)\n  \n  return(hour >= 9 && hour <= 17 && day %in% c(\"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\"))\n}\n\n#' Get comprehensive error tracking statistics\n#' @return List with all error tracking metrics and status\n#' @export\nget_error_tracking_statistics <- function() {\n  \n  list(\n    error_counts = .ERROR_TRACKING_STATE$error_counts,\n    health_status = .ERROR_TRACKING_STATE$health_status,\n    error_patterns = length(.ERROR_TRACKING_STATE$error_patterns),\n    alert_history = length(.ERROR_TRACKING_STATE$alert_history),\n    total_errors_stored = length(.ERROR_TRACKING_STATE$errors),\n    system_uptime_hours = calculate_system_uptime(),\n    last_error = if (length(.ERROR_TRACKING_STATE$errors) > 0) {\n      tail(.ERROR_TRACKING_STATE$errors, 1)[[1]]$timestamp\n    } else NULL\n  )\n}\n\ncat(\"\ud83d\udea8 Error Tracking & Health Check System loaded - Week 8 Performance\\n\")\ncat(\"   Comprehensive error management for Brazilian Legislative Monitor on Railway\\n\")\n\n# Define the %||% operator if not already defined\nif (!exists(\"%||%\")) {\n  `%||%` <- function(x, y) if (is.null(x)) y else x\n}\n\n# Initialize system start time for uptime tracking\nif (!exists(\".ERROR_TRACKING_STATE\") || is.null(.ERROR_TRACKING_STATE$system_start_time)) {\n  if (!exists(\".ERROR_TRACKING_STATE\")) .ERROR_TRACKING_STATE <- list()\n  .ERROR_TRACKING_STATE$system_start_time <- Sys.time()\n}"